package ai.graine.inapp

import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * EVERY ANSWER HERE WAS PRODUCED BY THE TYPESCRIPT THAT ALREADY WORKS.
 *
 * sdk/contract/native-calls.json is generated by
 * sdk/contract/generate-native-calls.mjs from sdk/inapp's built code: every
 * mu-law byte, six decode cases, three echo-guard scenarios, the context
 * token, the ticket's metadata, spoken captions and the frame constants. The
 * iOS and Android call engines both read it, so the three cannot drift apart.
 */
class NativeCallVectorsTest {
    private val text: String by lazy {
        var dir: File? = File("").absoluteFile
        while (dir != null && !File(dir, "sdk/contract/native-calls.json").exists() && !File(dir, "contract/native-calls.json").exists()) {
            dir = dir.parentFile
        }
        val f = listOf(File(dir, "sdk/contract/native-calls.json"), File(dir, "contract/native-calls.json")).firstOrNull { it.exists() }
            ?: error("sdk/contract/native-calls.json missing — run sdk/contract/generate-native-calls.mjs")
        f.readText()
    }

    /** Key order matters (it is in the token's bytes), and org.json's JVM build does not keep it. */
    @Suppress("UNCHECKED_CAST")
    private val vectors: Map<String, Any?> by lazy { OrderedJson.parse(text) as Map<String, Any?> }

    @Suppress("UNCHECKED_CAST")
    private fun list(v: Any?): List<Any?> = v as List<Any?>
    @Suppress("UNCHECKED_CAST")
    private fun obj(v: Any?): Map<String, Any?> = v as Map<String, Any?>
    private fun int(v: Any?): Int = (v as Number).toInt()

    @Test fun decodesEveryMuLawByteAsG711Does() {
        val expected = list(vectors["mulaw"]).map { int(it).toShort() }.toShortArray()
        val got = AgentAudio.decodeMuLaw(ByteArray(256) { it.toByte() })
        assertArrayEquals(expected, got)
    }

    @Test fun decodesAgentAudioExactlyAsTheTypeScriptDoes() {
        val cases = list(vectors["decode"])
        assertEquals(6, cases.size)
        for (c in cases.map(::obj)) {
            val name = c["name"] as String
            val declared = obj(c["declared"])
            val latched = c["latched"]?.let { obj(it) }?.let { AgentAudioFormat(kind(it["kind"] as String), int(it["sampleRate"])) }
            val d = AgentAudio.decode(
                B64.decode(c["data"] as String),
                declared["format"] as String?,
                declared["sampleRate"]?.let { int(it) },
                latched,
                AgentAudio.PCM_RATE,
            )
            val e = obj(c["expect"])
            assertNotNull(name, d)
            d!!
            assertEquals("$name: kind", e["kind"], d.kind.wire)
            assertEquals("$name: rate", int(e["sampleRate"]), d.sampleRate)
            assertEquals("$name: samples", int(e["samples"]), d.pcm16.size)
            val latch = e["latch"]?.let { obj(it) }
            if (latch == null) assertNull("$name: must not latch", d.latch)
            else {
                assertEquals("$name: latch kind", latch["kind"], d.latch?.kind?.wire)
                assertEquals("$name: latch rate", int(latch["sampleRate"]), d.latch?.sampleRate)
            }
            assertEquals("$name: head", list(e["head"]).map(::int), d.pcm16.take(8).map { it.toInt() })
            assertEquals("$name: tail", list(e["tail"]).map(::int), d.pcm16.takeLast(4).map { it.toInt() })
        }
    }

    private fun kind(s: String) = if (s == "mulaw") AgentAudioFormat.Kind.MULAW else AgentAudioFormat.Kind.PCM

    @Test fun theEchoGuardReleasesTheSameFramesAtTheSameSteps() {
        val scenarios = list(vectors["echoGuard"]).map(::obj)
        assertEquals(3, scenarios.size)
        for (s in scenarios) {
            val name = s["name"] as String
            val frameMs = (s["frameMs"] as Number).toDouble()
            val guard = EchoGuard<String>()
            list(s["steps"]).map(::obj).forEachIndexed { i, step ->
                val amp = (step["amp"] as Number).toDouble()
                val pcm = ShortArray(320) { n -> Math.round(amp * Math.sin((2 * Math.PI * 220 * n) / 16000)).toInt().toShort() }
                val released = guard.filter("f$i", pcm, step["audible"] as Boolean, frameMs)
                assertEquals("$name, step $i", list(step["released"]), released)
            }
        }
    }

    @Test fun theContextTokenIsTheTypeScriptsByteForByte() {
        val cases = list(vectors["contextToken"]).map(::obj)
        assertEquals(4, cases.size)
        for (c in cases) {
            assertEquals(c["name"] as String, c["expect"], CallVariables.contextToken(obj(c["vars"]), c["callType"] as String))
        }
    }

    @Test fun theTicketCarriesWhatTheTypeScriptPutsOnIt() {
        val t = obj(vectors["ticketMetadata"])
        val limits = obj(t["limits"])
        assertEquals(int(limits["keys"]), CallVariables.TICKET_KEYS)
        assertEquals(int(limits["keyLength"]), CallVariables.TICKET_KEY_LENGTH)
        assertEquals(int(limits["valueLength"]), CallVariables.TICKET_VALUE_LENGTH)
        assertEquals(int(limits["totalBytes"]), CallVariables.TICKET_TOTAL_BYTES)
        val cases = list(t["cases"]).map(::obj)
        assertEquals(8, cases.size)
        for (c in cases) {
            val got = CallVariables.forTicket(obj(c["vars"]))
            val expect = c["expect"]?.let { obj(it) }
            assertEquals(c["name"] as String, expect, got)
            // And in the same order: the first twelve keys are the ones kept.
            if (expect != null) assertEquals(c["name"] as String, expect.keys.toList(), got!!.keys.toList())
        }
    }

    @Test fun spokenPhrasesAreJoinedAsTheTypeScriptJoinsThem() {
        val cases = list(vectors["spokenJoin"]).map(::obj)
        assertEquals(6, cases.size)
        for (c in cases) {
            val chunks = list(c["chunks"]).map { it as String }
            val joined = chunks.fold("") { so, next -> so + CallText.spokenJoinGap(so, next) + next }
            assertEquals(c["expect"], joined)
        }
    }

    @Test fun theConstantsAreTheContracts() {
        val f = obj(vectors["frames"])
        assertEquals(f["subprotocol"], CallFrames.SUBPROTOCOL)
        assertEquals(int(f["pingMs"]).toLong(), CallFrames.PING_MS)
        assertEquals(int(f["socketOpenTimeoutMs"]).toLong(), CallFrames.OPEN_TIMEOUT_MS)
        assertEquals(int(f["actionDeadlineMs"]).toLong(), CallFrames.ACTION_DEADLINE_MS)
        assertEquals(int(f["agentPcmRate"]), AgentAudio.PCM_RATE)
        assertEquals(int(f["captureRate"]), AgentAudio.CAPTURE_RATE)
        assertEquals((f["minPlayoutBufferSeconds"] as Number).toDouble(), PlayoutBuffer.MIN_START_SECONDS, 0.0)
        assertEquals(int(f["drainAfterMs"]).toLong(), PlayoutBuffer.DRAIN_AFTER_MS)
        assertEquals(int(f["markAckCapMs"]).toLong(), CallFrames.MARK_ACK_CAP_MS)
        assertEquals(int(f["agentAudibleRecencyMs"]).toLong(), CallFrames.AGENT_AUDIBLE_RECENCY_MS)
        assertEquals(int(f["speakingTailMs"]).toLong(), CallFrames.SPEAKING_TAIL_MS)
        assertEquals(Protocol.ACTION_DEADLINE_MS, CallFrames.ACTION_DEADLINE_MS)
    }

    /** What goes on the socket, shape for shape, with the vector's placeholders filled in. */
    @Test fun everyOutboundFrameHasTheContractsShape() {
        val f = obj(vectors["frames"])
        fun same(expected: Any?, actualJson: String) = assertEquals(canon(expected), canon(OrderedJson.parse(actualJson)))

        val init = obj(f["init"]).toMutableMap()
        init["meta_data"] = obj(init["meta_data"]).toMutableMap().also { it["client"] = "graine-android-sdk" }
        same(init, CallFrames.init(mapOf("who_called" to "agent")))

        val audio = obj(f["audio"]).toMutableMap().also { it["data"] = "AAAA" }
        same(audio, CallFrames.audio("AAAA"))

        same(f["bargeIn"], CallFrames.BARGE_IN)
        same(f["ping"], CallFrames.PING)
        same(f["stop"], CallFrames.STOP)
        same(obj(f["markAck"]).toMutableMap().also { it["name"] = "m-1" }, CallFrames.markAck("m-1"))

        val result = obj(f["actionResult"]).toMutableMap().also { it["action_id"] = "a1"; it["status"] = "refused"; it["message"] = "No." }
        same(result, CallFrames.actionResult("a1", ActionResult.refused("No.")))
        // An ok with nothing to say carries no message; data rides along when there is some.
        same(mapOf("type" to "app_action_result", "action_id" to "a2", "status" to "ok"), CallFrames.actionResult("a2", ActionResult.ok()))
        same(mapOf("type" to "app_action_result", "action_id" to "a3", "status" to "ok", "message" to "Done", "data" to mapOf("ref" to "R1")),
            CallFrames.actionResult("a3", ActionResult.ok("Done", mapOf("ref" to "R1"))))

        assertEquals("{wsHost}/chat/v1/{agentId}?webcall=1", f["directUrl"])
        assertEquals("wss://ws.graine.ai/chat/v1/agent%201?webcall=1", CallUrls.direct(null, "agent 1"))
        assertEquals("wss://ws.graine.ai/chat/v1/a?webcall=1", CallUrls.direct("wss://ws.graine.ai/", "a"))
    }

    @Test fun theContextTokenRidesWhicheverUrlWasChosen() {
        val token = CallVariables.contextToken(mapOf("who_called" to "agent"))!!
        val encoded = CallUrls.encodeURIComponent(token)
        assertTrue("base64's + / = are escaped", !encoded.contains('+') && !encoded.contains('/') && !encoded.contains('='))
        assertEquals("wss://ws.graine.ai/s?context_token=$encoded", CallUrls.withToken("wss://ws.graine.ai/s", token))
        assertEquals("wss://ws.graine.ai/s?x=1&context_token=$encoded", CallUrls.withToken("wss://ws.graine.ai/s?x=1", token))
        assertEquals("no token, no parameter", "wss://ws.graine.ai/s", CallUrls.withToken("wss://ws.graine.ai/s", null))
        assertEquals("%E0%A4%B0%20!~*'()", CallUrls.encodeURIComponent("र !~*'()"))
    }

    @Test fun theAppContextFrameIsTheSdksFrameInTheRuntimesSpelling() {
        val frame = JSONObject().put("context", JSONObject().put("screen", "kyc")).put("availableActions", org.json.JSONArray(listOf("open_screen"))).put("seq", 3)
        val wire = JSONObject(CallFrames.appContext(frame))
        assertEquals("app_context", wire.getString("type"))
        assertEquals("kyc", wire.getJSONObject("context").getString("screen"))
        assertEquals("open_screen", wire.getJSONArray("available_actions").getString(0))
        assertEquals(3, wire.getInt("seq"))
        assertTrue("absent stays absent: [] would forbid every action", !JSONObject(CallFrames.appContext(JSONObject().put("context", JSONObject()))).has("available_actions"))
    }

    /** Comparable shapes: maps by key, numbers as doubles. */
    private fun canon(v: Any?): Any? = when (v) {
        is Map<*, *> -> v.entries.associate { (k, x) -> k.toString() to canon(x) }.toSortedMap()
        is List<*> -> v.map { canon(it) }
        is Number -> v.toDouble()
        else -> v
    }
}

/** A small JSON reader that keeps object key order (LinkedHashMap). Test-only. */
internal object OrderedJson {
    fun parse(s: String): Any? {
        val p = P(s)
        val v = p.value()
        p.ws()
        require(p.i == s.length) { "trailing input at ${p.i}" }
        return v
    }

    private class P(val s: String) {
        var i = 0
        fun ws() { while (i < s.length && s[i].isWhitespace()) i++ }
        fun value(): Any? {
            ws()
            return when (val c = s[i]) {
                '{' -> obj()
                '[' -> arr()
                '"' -> str()
                't' -> lit("true", true)
                'f' -> lit("false", false)
                'n' -> lit("null", null)
                else -> if (c == '-' || c.isDigit()) num() else error("unexpected '$c' at $i")
            }
        }
        fun lit(word: String, v: Any?): Any? { require(s.startsWith(word, i)); i += word.length; return v }
        fun obj(): Map<String, Any?> {
            val m = LinkedHashMap<String, Any?>()
            i++; ws()
            if (s[i] == '}') { i++; return m }
            while (true) {
                ws(); val k = str(); ws(); require(s[i] == ':'); i++
                m[k] = value(); ws()
                if (s[i] == ',') { i++; continue }
                require(s[i] == '}'); i++; return m
            }
        }
        fun arr(): List<Any?> {
            val l = ArrayList<Any?>()
            i++; ws()
            if (s[i] == ']') { i++; return l }
            while (true) {
                l.add(value()); ws()
                if (s[i] == ',') { i++; continue }
                require(s[i] == ']'); i++; return l
            }
        }
        fun str(): String {
            require(s[i] == '"'); i++
            val sb = StringBuilder()
            while (true) {
                val c = s[i++]
                when (c) {
                    '"' -> return sb.toString()
                    '\\' -> when (val e = s[i++]) {
                        'n' -> sb.append('\n'); 't' -> sb.append('\t'); 'r' -> sb.append('\r')
                        'b' -> sb.append('\b'); 'f' -> sb.append('\u000C')
                        'u' -> { sb.append(s.substring(i, i + 4).toInt(16).toChar()); i += 4 }
                        else -> sb.append(e)
                    }
                    else -> sb.append(c)
                }
            }
        }
        fun num(): Number {
            val start = i
            if (s[i] == '-') i++
            while (i < s.length && (s[i].isDigit() || s[i] in ".eE+-")) i++
            val t = s.substring(start, i)
            return if (t.any { it in ".eE" }) t.toDouble() else t.toLong().let { if (it in Int.MIN_VALUE..Int.MAX_VALUE) it.toInt() else it }
        }
    }
}
